self.onmessage=async({data})=>{let output='';try{importScripts('https://cdn.jsdelivr.net/pyodide/v0.27.7/full/pyodide.js');const py=await loadPyodide({indexURL:'https://cdn.jsdelivr.net/pyodide/v0.27.7/full/',stdout:s=>{if(output.length<20000)output+=s+'\n'},stderr:s=>{if(output.length<20000)output+=s+'\n'}});self.postMessage({type:'ready'});const answers=data.inputs?data.inputs.split('\n'):[];py.setStdin({stdin:()=>answers.length?answers.shift():null});const globals=py.toPy({});let error='',passed=false,checkError='';try{await py.runPythonAsync(data.source,{globals})}catch(e){error=e.message.split('\n').slice(-5).join('\n')}if(!error&&data.expected!==null){passed=output.trim()===data.expected.trim();if(passed&&data.check){try{globals.set('source',data.source);py.runPython(data.check,{globals})}catch(e){passed=false;checkError=e.message.split('\n').filter(x=>x.includes('AssertionError')).pop()||'Check that you used the technique in the mission.'}}if(passed&&data.cases){for(const [score,expected] of data.cases){const testSource=data.source.replace(/score\s*=\s*85/,`score = ${score}`);output='';try{await py.runPythonAsync(testSource,{globals});if(output.trim()!==expected){passed=false;checkError=`Try score = ${score}. It should print ${expected}.`;break}}catch(e){passed=false;checkError='Check all branches of your reward system.';break}}output='Gold\n';}}globals.destroy();self.postMessage({type:'result',output,error,passed,checkError})}catch(e){self.postMessage({type:'result',output,error:'Unable to load Python. Check your internet connection and try again.',passed:false})}};
